if (-not (Get-Command Invoke-Hook -ErrorAction SilentlyContinue)) { . (Join-Path $PSScriptRoot '_HookHarness.ps1') }
$scripts=(Resolve-Path (Join-Path $PSScriptRoot '..\..\scripts')).Path
$ps=Join-Path $scripts 'warehouse-map-check.ps1'
function Put($p,$t){$d=Split-Path -Parent $p;if($d){New-Item -ItemType Directory -Force $d|Out-Null};[IO.File]::WriteAllText($p,$t,[Text.UTF8Encoding]::new($false))}
function Fixture([bool]$Warehouse=$true){$r=Join-Path ([IO.Path]::GetTempPath()) ('warehouse-map-'+[guid]::NewGuid());New-Item -ItemType Directory -Force $r|Out-Null;if($Warehouse){Put (Join-Path $r 'warehouse/DimCustomer.sql') 'CREATE TABLE dw.DimCustomer (CustomerKey int, EffectiveFrom date, IsCurrent bit);';Put (Join-Path $r 'warehouse/usp_LoadCustomer.sql') 'CREATE PROC etl.usp_LoadCustomer @BatchId int AS SELECT 1;'};$r}
function Check($r,$exit,$text,$ctx=''){$p=RunArg $ps $r;Assert ($p.Exit-eq$exit) "$ctx ps exit $($p.Exit): $($p.Out) $($p.Err)";Assert ($p.Out-match$text) "$ctx ps missing $text`: $($p.Out)"}
function Drop([string[]]$Paths){foreach($x in $Paths){if($x){Remove-Item -LiteralPath $x -Recurse -Force -ErrorAction SilentlyContinue}}}
function Hex($b){[BitConverter]::ToString($b).Replace('-','').ToLowerInvariant()}
function GitRun([string[]]$GitArgs){$null=& git -c user.name=test -c user.email=test@example.invalid -c commit.gpgsign=false @GitArgs 2>&1;if($LASTEXITCODE-ne0){throw "git $($GitArgs -join ' ') exit $LASTEXITCODE"}}
function GitInit($r){GitRun @('-C',$r,'init','-q');GitRun @('-C',$r,'add','-A');GitRun @('-C',$r,'commit','-q','-m','fixture')}
# A placeholder unique per call when -Digest fails, so a case goes red on the harm it guards (two digests "agree", a
# deleted table reads current) and not only on the missing switch.
function Digest($r){$p=RunArg $ps @($r,'-Digest');if($p.Exit-eq0-and$p.Out-match'^digest=([0-9a-f]{16})$'){$Matches[1]}else{'nodigest-'+[guid]::NewGuid().ToString('N')}}
function Stamp($r,$d=(Digest $r),$extra=''){Put (Join-Path $r 'docs/warehouse-map.md') "<!-- warehouse-map full pass: 2026-11-19T12:00Z digest=$d -->`n# map$extra"}
Reset-Tests
It 'non-warehouse and excluded generated/vendor signals are not applicable' {$r=Fixture $false;try{Put (Join-Path $r 'VENDOR/warehouse/DimDecoy.sql') 'CREATE TABLE dw.DimDecoy (IsCurrent bit);';Put (Join-Path $r 'BUILD/warehouse/usp_LoadDecoy.sql') 'CREATE PROC etl.usp_LoadDecoy @BatchId int AS SELECT 1;';Check $r 0 'not-applicable';$missing=Join-Path $r 'missing-root';$p=RunArg $ps $missing;Assert ($p.Exit-eq 2) "PowerShell missing root exit=$($p.Exit)"}finally{Remove-Item -Recurse -Force $r}}
It 'warehouse without map fails' {$r=Fixture;try{Check $r 1 'missing';New-Item -ItemType Directory -Force (Join-Path $r 'docs/warehouse-map.md')|Out-Null;Check $r 1 'missing'}finally{Remove-Item -Recurse -Force $r}}
It 'a scoped write keeps the last full pass''s staleness' {$r=Fixture;try{Stamp $r;Check $r 0 'current';Put (Join-Path $r 'warehouse/FactSale.sql') 'CREATE TABLE dw.FactSale (BatchId int);';Check $r 1 'stale \(warehouse artifacts changed since the full pass\)';$m=Join-Path $r 'docs/warehouse-map.md';Put $m ([IO.File]::ReadAllText($m)+"`n| dw.FactSale | fact |");Check $r 1 'stale \(warehouse artifacts changed since the full pass\)' 'after the scoped rewrite:';Stamp $r;Check $r 0 'current' 'after the next full pass:'}finally{Drop $r}}
It 'a map no full pass has written stays stale' {$r=Fixture;try{Put (Join-Path $r 'docs/warehouse-map.md') "<!-- warehouse-map full pass: none -->`n# map";Check $r 1 'stale \(no full pass yet\)'}finally{Drop $r}}
It 'the remedy names /map-warehouse only where that skill is installed' {$r=Fixture $false;try{Put (Join-Path $r 'azure-pipelines.yml') 'trigger: none';Put (Join-Path $r 'load.sql') 'SELECT @BatchId;';$p=RunArg $ps $r;Assert ($p.Exit-eq1-and$p.Out-match'missing') "no-skill fixture: exit=$($p.Exit) $($p.Out)";Assert ($p.Out-notmatch'/map-warehouse') "no-skill remedy names a skill that is not installed: $($p.Out)";Assert ($p.Out-match'inspect the live schema') "no-skill remedy: $($p.Out)";Put (Join-Path $r 'docs/warehouse-map.md') "<!-- warehouse-map full pass: none -->`n# map";$p=RunArg $ps $r;Assert ($p.Exit-eq1-and$p.Out-match'stale \(no full pass yet\)'-and$p.Out-notmatch'/map-warehouse') "no-skill stale remedy: exit=$($p.Exit) $($p.Out)";Remove-Item -LiteralPath (Join-Path $r 'docs/warehouse-map.md') -Force;Put (Join-Path $r '.claude/skills/map-warehouse/SKILL.md') 'skill';$p=RunArg $ps $r;Assert ($p.Exit-eq1-and$p.Out-match'run /map-warehouse') "skill present, remedy must name it: exit=$($p.Exit) $($p.Out)"}finally{Drop $r}}
It 'current and stale maps are distinguished without unrelated JSON false positives' {$r=Fixture;try{Put (Join-Path $r 'docs/warehouse-map.md') '# map';Check $r 1 'stale \(no content stamp; a full pass records one\)' 'unstamped map:';Stamp $r;Check $r 0 'current';Put (Join-Path $r 'package.json') '{"version":"2"}';Check $r 0 'current';Put (Join-Path $r 'warehouse/FactSale.sql') 'CREATE TABLE dw.FactSale (BatchId int);';Check $r 1 'stale'
    $probe=Join-Path $r 'probe';New-Item -ItemType Directory -Force $probe|Out-Null
    Copy-Item -LiteralPath (Join-Path $scripts 'warehouse-signals.tsv') -Destination $probe
    $probePs=Join-Path $probe 'warehouse-map-check.ps1';$psText=[IO.File]::ReadAllText($ps);$psBroken=$psText.Replace('try { $matched = $file.Name -match $parts[1] -or (Select-String -LiteralPath $file.FullName -Pattern $parts[1] -Quiet -ErrorAction Stop) }',"try { throw 'simulated read failure' }");Assert ($psBroken-ne$psText) 'PowerShell read-failure mutation missed';Put $probePs $psBroken
    $p=RunArg $probePs $r;$pText=$p.Out+"`n"+$p.Err;Assert ($p.Exit-eq 2-and$pText-match'Could not read warehouse artifact') "PowerShell artifact read failure was not explicit: exit=$($p.Exit) $pText"
    Copy-Item -LiteralPath $ps -Destination $probePs -Force;Put (Join-Path $probe 'warehouse-signals.tsv') "broken-only-one-field`n"
    $p=RunArg $probePs $r;Assert($p.Exit-eq2)"PowerShell malformed signal exit=$($p.Exit)"
}finally{Remove-Item -Recurse -Force $r}}
# A OneDrive folder carries the ReparsePoint attribute with no LinkType (seen on this host's OneDrive root), and skipping on the bare attribute
# reported every warehouse under it as not-applicable. No test can give a folder that attribute without a filter driver, so the skip's
# predicate is asserted from the source beside the behaviour that must stay: a junction into the repository is still skipped.
It 'a junction is skipped for being a link, not for carrying the reparse attribute' {$r=Fixture $false;$outside=Join-Path ([IO.Path]::GetTempPath()) ('warehouse-outside-'+[guid]::NewGuid());try{Put (Join-Path $outside 'DimCustomer.sql') 'CREATE TABLE dw.DimCustomer (CustomerKey int, EffectiveFrom date, IsCurrent bit);';Put (Join-Path $outside 'usp_LoadCustomer.sql') 'CREATE PROC etl.usp_LoadCustomer @BatchId int AS SELECT 1;';$null=cmd.exe /d /c mklink /J (Join-Path $r 'warehouse') $outside;Assert ((Get-Item -LiteralPath (Join-Path $r 'warehouse')).LinkType-eq'Junction') 'fixture junction was not created';Check $r 0 'not-applicable';$text=[IO.File]::ReadAllText($ps);Assert ($text-match"LinkType -in @\('SymbolicLink', 'Junction'\)") 'the enumeration must skip by LinkType';Assert ($text-notmatch'Attributes -band \[IO\.FileAttributes\]::ReparsePoint') 'the enumeration still skips on the bare ReparsePoint attribute, which OneDrive folders carry';GitInit $r;Check $r 0 'not-applicable' 'Git lists files through a junction:'}finally{$null=cmd.exe /d /c rmdir (Join-Path $r 'warehouse');Remove-Item -Recurse -Force $r;Remove-Item -Recurse -Force $outside -ErrorAction SilentlyContinue}}
# Freshness was the file times, so a deleted or renamed table, or a row appended to an unstamped map, read current.
It 'a deleted artifact makes a stamped map stale, outside and inside Git' {foreach($git in $false,$true){$r=Fixture;try{Put (Join-Path $r 'warehouse/FactSale.sql') 'CREATE TABLE dw.FactSale (BatchId int);';if($git){GitInit $r};Stamp $r;Check $r 0 'current' "git=$git before:";Remove-Item -LiteralPath (Join-Path $r 'warehouse/FactSale.sql');Check $r 1 'stale \(warehouse artifacts changed since the full pass\)' "git=$git deleted:"}finally{Drop $r}}}
It 'a renamed artifact makes a stamped map stale' {$r=Fixture;try{Put (Join-Path $r 'warehouse/FactSale.sql') 'CREATE TABLE dw.FactSale (BatchId int);';Stamp $r;Check $r 0 'current';Move-Item -LiteralPath (Join-Path $r 'warehouse/FactSale.sql') -Destination (Join-Path $r 'warehouse/FactSales.sql');Check $r 1 'stale \(warehouse artifacts changed since the full pass\)' 'renamed:'}finally{Drop $r}}
It 'a row appended to an unstamped or digest-less map does not make it current' {$r=Fixture;try{$m=Join-Path $r 'docs/warehouse-map.md';Put $m '# map';Put (Join-Path $r 'warehouse/FactSale.sql') 'CREATE TABLE dw.FactSale (BatchId int);';Check $r 1 'stale \(no content stamp; a full pass records one\)' 'unstamped:';Put $m "# map`n| dw.FactSale | fact |";Check $r 1 'stale \(no content stamp; a full pass records one\)' 'row appended:';Put $m "<!-- warehouse-map full pass: 2026-11-19T12:00Z -->`n# map";Check $r 1 'stale \(no content stamp; a full pass records one\)' 'dated stamp without a digest:'}finally{Drop $r}}
It 'touching write times without changing content keeps the map current' {$r=Fixture;try{Stamp $r;Check $r 0 'current';foreach($f in Get-ChildItem -LiteralPath (Join-Path $r 'warehouse') -File){$f.LastWriteTimeUtc=[DateTime]::UtcNow.AddHours(1)};Check $r 0 'current' 'after touching:'}finally{Drop $r}}
It 'two clones with opposite core.autocrlf agree on the digest' {$src=Fixture;$a=$src+'-crlf';$b=$src+'-lf';try{Put (Join-Path $src 'warehouse/FactSale.sql') "CREATE TABLE dw.FactSale (`n    BatchId int`n);`n";GitInit $src;GitRun @('clone','-q','-c','core.autocrlf=true',$src,$a);GitRun @('clone','-q','-c','core.autocrlf=false',$src,$b);Assert ([IO.File]::ReadAllText((Join-Path $a 'warehouse/FactSale.sql')).Contains("`r`n")) 'the autocrlf=true clone has no CRLF';Assert (-not [IO.File]::ReadAllText((Join-Path $b 'warehouse/FactSale.sql')).Contains("`r")) 'the autocrlf=false clone has a CR';$da=Digest $a;$db=Digest $b;Assert ($da-eq$db) "the clones disagree: $da vs $db";Stamp $b $da;Check $b 0 'current' 'the other clone:'}finally{Drop @($src,$a,$b)}}
It 'an ignored generated folder does not change the digest' {$r=Fixture;try{Put (Join-Path $r '.gitignore') "target/`n";GitInit $r;$d=Digest $r;Stamp $r $d;Put (Join-Path $r 'target/compiled/warehouse/DimCustomer.sql') 'CREATE TABLE dw.DimCustomer (IsCurrent bit);';$after=Digest $r;Assert ($after-eq$d) "an ignored target/ changed the digest: $d vs $after";Check $r 0 'current' 'with target/:'}finally{Drop $r}}
It 'the digest hashes the ordinally sorted path and content-hash lines' {$r=Fixture;try{Put (Join-Path $r 'warehouse/B.sql') 'SELECT 1;';Put (Join-Path $r 'warehouse/a.sql') 'SELECT 2;';$rel=[string[]]@(Get-ChildItem -LiteralPath (Join-Path $r 'warehouse') -File|ForEach-Object{'warehouse/'+$_.Name});$culture=@($rel|Sort-Object);[Array]::Sort($rel,[StringComparer]::Ordinal);Assert (($culture-join'|')-ne($rel-join'|')) 'the fixture names sort the same either way';$sha=[Security.Cryptography.SHA256]::Create();$text=-join @($rel|ForEach-Object{$_+' '+(Hex ($sha.ComputeHash([IO.File]::ReadAllBytes((Join-Path $r $_)))))+"`n"});$want=(Hex ($sha.ComputeHash([Text.UTF8Encoding]::new($false).GetBytes($text)))).Substring(0,16);$p=RunArg $ps @($r,'-Digest');Assert ($p.Exit-eq0-and$p.Out-eq"digest=$want") "want digest=$want, got exit=$($p.Exit) $($p.Out) $($p.Err)"}finally{Drop $r}}
It 'a locked artifact is could-not-examine, never a verdict, outside and inside Git' {foreach($git in $false,$true){$r=Fixture $false;try{Put (Join-Path $r 'a.sql') 'CREATE TABLE dw.DimX (IsCurrent bit, BatchId int); -- usp_LoadX partition by ssis';Put (Join-Path $r 'warehouse/zz.sql') 'SELECT 1;';if($git){GitInit $r};Stamp $r;Check $r 0 'current' "git=$git unlocked:";$fs=[IO.File]::Open((Join-Path $r 'warehouse/zz.sql'),'Open','ReadWrite','None');try{$p=RunArg $ps $r}finally{$fs.Dispose()};Assert ($p.Exit-eq2) "git=$git locked artifact: exit=$($p.Exit) $($p.Out) $($p.Err)"}finally{Drop $r}}}
It 'a locked map is could-not-examine, never stale' {$r=Fixture;try{Stamp $r;$fs=[IO.File]::Open((Join-Path $r 'docs/warehouse-map.md'),'Open','ReadWrite','None');try{$p=RunArg $ps $r}finally{$fs.Dispose()};Assert ($p.Exit-eq2-and$p.Err-match'Could not read docs/warehouse-map\.md') "locked map: exit=$($p.Exit) $($p.Out) $($p.Err)"}finally{Drop $r}}
It 'the digest is printed only on request' {$r=Fixture;try{$p=RunArg $ps @($r,'-Digest');Assert ($p.Exit-eq0-and$p.Out-match'^digest=[0-9a-f]{16}$') "-Digest: exit=$($p.Exit) $($p.Out) $($p.Err)";$d=$p.Out.Substring(7);$verdicts=@((RunArg $ps $r).Out);Stamp $r $d;$verdicts+=(RunArg $ps $r).Out;Put (Join-Path $r 'warehouse/FactSale.sql') 'CREATE TABLE dw.FactSale (BatchId int);';$verdicts+=(RunArg $ps $r).Out;foreach($v in $verdicts){Assert ($v-match'^WAREHOUSE_MAP '-and$v-notmatch$d-and$v-notmatch'digest=') "a verdict line carries the digest: $v"}}finally{Drop $r}}
# Git lists a submodule as one gitlink entry, which is no file, so its SQL was invisible: a stale map read current and a
# warehouse held only in a submodule read not-applicable.
function SubRepo($r,[string[]]$Names){$s=$r+'-sub';foreach($n in $Names){Put (Join-Path $s $n) "CREATE TABLE dw.$([IO.Path]::GetFileNameWithoutExtension($n)) (BatchId int, IsCurrent bit); -- usp_Load partition by"};GitInit $s;GitRun @('-C',$r,'-c','protocol.file.allow=always','submodule','add','-q',$s,'warehouse/orders');GitRun @('-C',$r,'commit','-q','-m','submodule');$s}
It 'an edit or a new file inside a submodule makes a stamped map stale' {$r=Fixture;$s=$null;try{GitInit $r;$s=SubRepo $r @('FactOrder.sql');Stamp $r;Check $r 0 'current' 'submodule stamped:';Put (Join-Path $r 'warehouse/orders/FactOrder.sql') 'CREATE TABLE dw.FactOrder (BatchId int, NewCol int);';Check $r 1 'stale \(warehouse artifacts changed since the full pass\)' 'edited inside the submodule:';Stamp $r;Check $r 0 'current' 'restamped:';Put (Join-Path $r 'warehouse/orders/DimNew.sql') 'CREATE TABLE dw.DimNew (k int);';Check $r 1 'stale \(warehouse artifacts changed since the full pass\)' 'added inside the submodule:'}finally{Drop @($r,$s)}}
It 'a warehouse held only in a submodule is applicable' {$r=Fixture $false;$s=$null;try{Put (Join-Path $r 'README.md') '# app';GitInit $r;$s=SubRepo $r @('DimCustomer.sql','usp_LoadCustomer.sql');Check $r 1 'missing' 'warehouse only in a submodule:'}finally{Drop @($r,$s)}}
exit (Write-TestSummary 'WarehouseMapCheck.Tests')
